def blocks(inp,rows,cols):
    H,W=inp.shape
    rg=[];s=0
    for r in rows+[H]: rg.append(list(range(s,r))); s=r+1
    cg=[];s=0
    for c in cols+[W]: cg.append(list(range(s,c))); s=c+1
    return [[inp[np.ix_(rr,cc)] for cc in cg] for rr in rg]
